function mostCommon(xs: number[]): number {
  const counts = new Map<number, number>();
  for (const x of xs) counts.set(x, (counts.get(x) ?? 0) + 1);
  let best = xs[0];
  for (const [value, n] of counts) {
    if (n > (counts.get(best) ?? 0)) best = value;
  }
  return best;
}

